"""Owner rule 2026-11-16: the folder decides the kind of picture — `frigate` = camera, `output` = generated by Kåre,
`input` = uploaded by the user.
- every camera path (camera tool picture, show_event, a question card's picture) stores its chat copy in the user's
  `frigate` folder and never reads `input`/`output` (the camera code does not use find_image/list_images at all);
- `view_images` is the user's own uploaded/generated pictures: it never lists or shows a `frigate` picture;
- the chat route still serves the owner's own camera picture.
Tmp folders only. Placeholders only."""

import asyncio
import base64
from pathlib import Path

import pytest

from kaare_core import image_store
from kaare_core.domain import frigate_store as domain_store
from kaare_core.memory import chat_questions
from kaare_core.routers import router_media
from kaare_core.tools import executor, executor_camera
from tests.test_p149_j11_chat_questions import env  # noqa: F401  (env is a fixture)

JPEG = b"\xff\xd8fake-jpeg\xff\xd9"


@pytest.fixture
def folders(env, monkeypatch):  # noqa: F811  (env: the shared fixture imported above)
    monkeypatch.setattr(image_store, "_IMAGES_ROOT", env / "images")

    async def snap(camera):
        return base64.b64encode(JPEG).decode()

    async def no_rest(event_id):
        raise RuntimeError("no Frigate in tests")

    monkeypatch.setattr(executor_camera, "fetch_snapshot_b64", snap)
    monkeypatch.setattr(executor_camera, "fetch_event_snapshot", no_rest)
    monkeypatch.setattr(executor_camera, "_audit", lambda *a, **k: None)
    monkeypatch.setattr(executor_camera, "_may_analyse", lambda uid: False)
    domain_store.SNAPSHOT_DIR.mkdir(parents=True, exist_ok=True)
    (domain_store.SNAPSHOT_DIR / "e0.jpg").write_bytes(JPEG)
    return env / "images" / "user_a"


def _files(d: Path, sub: str) -> list[str]:
    return sorted(p.name for p in (d / sub).glob("*")) if (d / sub).exists() else []


def test_camera_pictures_land_in_the_frigate_folder(folders):
    asyncio.run(executor_camera._kamera({"action": "snapshot", "camera": "cam_a", "_user_id": "user_a"}, "nb"))
    asyncio.run(executor_camera._kamera({"action": "show_event", "event_id": "e0", "_user_id": "user_a"}, "nb"))
    chat_questions.picture_line("user_a", "e0", "nb")
    assert len(_files(folders, "frigate")) == 3
    assert _files(folders, "input") == [] and _files(folders, "output") == []


def test_the_camera_code_never_reads_the_users_own_folders():
    src = Path(executor_camera.__file__).read_text() + Path(chat_questions.__file__).read_text()
    assert "find_image" not in src and "list_images" not in src


def test_view_images_never_lists_or_shows_camera_pictures(folders):
    cam = image_store.save_image(JPEG, "user_a", "frigate", ext="jpg")
    own = image_store.save_image(JPEG, "user_a", "output", ext="png")
    listed = asyncio.run(executor._dispatch("view_images", {"_user_id": "user_a"}))
    assert own in listed and cam not in listed
    shown = asyncio.run(executor._dispatch("view_images", {"_user_id": "user_a", "image_id": cam}))
    assert "/api/image/" not in shown


def test_the_chat_route_still_serves_the_owners_camera_picture(folders):
    cam = image_store.save_image(JPEG, "user_a", "frigate", ext="jpg")
    res = asyncio.run(router_media.api_serve_image(cam, _u={"sub": "user_a", "role": "adult"}))
    assert "/frigate/" in str(res.path)
